def crest(fill, opacity=None):
    """크레스트 SVG 조각 — `svg.data_uri()` 의 body 로 넣는다."""
    op = f" opacity='{opacity}'" if opacity is not None else ""
    f = (fill or "").replace("#", "%23")
    return "".join(f"<path fill='{f}'{op} d='{d}'/>" for d in CREST_PATHS)

