def mark(fill, opacity=None):
    """판권면 로고 SVG 조각."""
    op = f" opacity='{opacity}'" if opacity is not None else ""
    f = (fill or "").replace("#", "%23")
    return "".join(f"<path fill='{f}'{op} d='{d}'/>" for d in MARK_PATHS)
